#endif
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define int long long
#define endl "\n"

void solve() {
    int n, k;
    cin >> n >> k;
    map<int, int> positive_review, negative_review;
    priority_queue<int, vector<int>, greater<>> prices;

    for (int i = 0; i < n; i++) {
        int a;
        cin >> a;
        positive_review[a]++;
        prices.emplace(a);
    }

    for (int i = 0; i < n; i++) {
        int a;
        cin >> a;
        negative_review[a]++;
        prices.emplace(a);
    }

    int best = 0;
    int negative = 0;
    int last = -1;
    while (!prices.empty()) {
        int price = prices.top();
        prices.pop();
        if (price == last)
            continue;
        last = price;
        int cur = n * price;
        if (negative <= k)
            best = max(best, n * price);
        negative += positive_review[price];
        negative -= negative_review[price];
        n -= negative_review[price];
    }

    cout << best << endl;
}

signed main() {
    #ifndef ONLINE_JUDGE
